export const INITIAL_PRODUCTS: Product[] = RAW_CATALOG.map((r) => {
  const images = r[13].map((idx) => IMG_POOL[idx] || IMG_POOL[0]);
  const base: Product = {
    id: r[0],
    name: r[1],
    brand: r[2],
    model: r[3],
    originalPrice: r[4],
    sellingPrice: r[5],
    discountPercentage: r[6],
    ram: r[7],
    storage: r[8],
    color: r[9],
    availableColors: ["Black", "Blue", "Silver"],
    condition: r[10] as DeviceCondition,
    batteryHealth: r[11],
    stock: r[12],
    images,
    primaryImage: images[0],
    description: `Certified pre-owned ${r[1]} (${r[14]}) in ${r[10]} condition. Tested across 32 comprehensive hardware checkpoints. 100% genuine Indian unit. Note: RAM, storage and display depend on variant; verified on inspection.`,
    specs: {
      display: "",
      processor: "",
      camera: "",
      battery: `${r[11]}% Certified Health`,
      os: "",
      network: ""
    },
    accessories: [
      "Verified Safe Fast Charger",
      "Type-C / Lightning Cable",
      "Phone Bazar Certified Packaging",
      "Warranty Card"
    ],
    warrantyInfo: "6 Months Phone Bazar Warranty + 7 Days Replacement",
    launchYear: r[14],
    isFeatured: Boolean(r[15]),
    isBestDeal: Boolean(r[16]),
    isLatestArrival: Boolean(r[17]),
    rating: r[18],
    reviewCount: r[19]
  };
  return enrichProductSpecs(base);
});
